// Проверка токена приёмки и разбор данных с флешки. Чужие и битые данные отбрасываются. Нужен модуль crypto (NODE_FUNCTION_ALLOW_BUILTIN).
const crypto = require('crypto');
const hdr = String(($json.headers && $json.headers['x-radar-token']) || '');
const need = String($env.INTAKE_TOKEN || '');
const same = need.length >= 16 && hdr.length === need.length && crypto.timingSafeEqual(Buffer.from(hdr), Buffer.from(need));
if (!same) return { json: { auth: false, valid: false, errors: ['неверный токен'] } };
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const clean = (s) => String(s == null ? '' : s).toUpperCase().replace(/[^A-Z0-9-]/g, '').slice(0, 40);
const text = (s) => String(s == null ? '' : s).replace(/[^\wА-Яа-я .,+()\/-]/g, '').slice(0, 60);
const num = (x, lo, hi) => { const n = Number(x); return x === null || x === undefined || x === '' || !Number.isFinite(n) ? null : Math.min(hi, Math.max(lo, n)); };
const board = clean(b.board_serial), chassis = clean(b.chassis_serial), sticker = clean(b.sticker_serial);
const errors = [];
if (!board) errors.push('нет серийника платы');
if (!chassis) errors.push('нет прошитого серийника системы');
if (!sticker) errors.push('нет серийника с наклейки');
const bat = b.battery || {}, ssd = b.ssd || {}, fl = b.flags || {};
const device = {
  board_serial: board, chassis_serial: chassis, sticker_serial: sticker,
  serial_match: !!sticker && sticker === chassis,
  model: text(b.model), bios_vendor: text(b.bios_vendor), bios_version: text(b.bios_version),
  battery_wear_pct: num(bat.wear_pct, 0, 100), battery_cycles: num(bat.cycles, 0, 100000),
  ssd_health_pct: num(ssd.health_pct, 0, 100), ssd_kind: text(ssd.kind), ssd_passed: typeof ssd.passed === 'boolean' ? ssd.passed : null,
  flags: {
    checked: fl.checked === true,
    mdm_enrollment_keys: num(fl.mdm_enrollment_keys, 0, 1000),
    autopilot_keys: num(fl.autopilot_keys, 0, 1000),
    acpi_msdm: typeof fl.acpi_msdm === 'boolean' ? fl.acpi_msdm : null,
    reason: text(fl.reason),
  },
};
return { json: { auth: true, valid: errors.length === 0, errors, device, serials: [board, chassis, sticker].filter(Boolean).join(',') } };

// Решение по сделке: запрет, ручная проверка или лимит цены. Система только ВЫЯВЛЯЕТ корпоративные следы и не снимает блокировки.
// Отсутствие следов при непроверенных флагах не считается «чисто»: такой ноутбук уходит на ручную проверку.
const src = $('Принять и проверить данные').item.json;
const d = src.device;
const stopReason = $json.stop_reason || null;
const base = $json.base_price === null || $json.base_price === undefined ? null : Number($json.base_price);
const reasons = [];
let forbidden = false, review = false;
if (stopReason) { forbidden = true; reasons.push('серийник в стоп-листе: ' + stopReason); }
if (!d.serial_match) { forbidden = true; reasons.push('серийник на наклейке не совпал с прошитым в плату: возможна замена платы'); }
if ((d.flags.mdm_enrollment_keys || 0) > 0) { forbidden = true; reasons.push('найдены следы корпоративной привязки MDM'); }
if ((d.flags.autopilot_keys || 0) > 0) { forbidden = true; reasons.push('найдены следы Windows Autopilot'); }
if (!d.flags.checked) { review = true; reasons.push('офлайн-признаки MDM и Autopilot не проверены' + (d.flags.reason ? ' (' + d.flags.reason + ')' : '')); }
if (d.battery_wear_pct === null) { review = true; reasons.push('износ батареи не прочитан'); }
if (d.ssd_health_pct === null) { review = true; reasons.push('состояние SSD не прочитано'); }
else if (d.ssd_passed === false || d.ssd_health_pct < 50) { review = true; reasons.push('SSD в плохом состоянии: ' + d.ssd_health_pct + '%'); }
if (base === null) { review = true; reasons.push('для модели нет цены в price_rules'); }
const cb = d.battery_wear_pct === null ? 0 : (d.battery_wear_pct <= 20 ? 0 : d.battery_wear_pct <= 40 ? 0.05 : d.battery_wear_pct <= 60 ? 0.12 : 0.25);
const cs = d.ssd_health_pct === null ? 0 : (d.ssd_health_pct >= 90 ? 0 : d.ssd_health_pct >= 80 ? 0.05 : d.ssd_health_pct >= 60 ? 0.15 : 0.35);
const formula = base === null ? null : Math.round(base * (1 - cb) * (1 - cs) / 100) * 100;
const verdict = forbidden ? 'forbidden' : (review ? 'review' : 'allow');
return { json: { device: d, verdict, reasons, base_price: base, price_formula: forbidden ? null : formula, coef_battery: cb, coef_ssd: cs } };

// В модель уходят только числа расчёта: серийники, текст страницы и данные продавца не передаются.
const d = $json;
const prompt = 'Ты помощник приёмщика техники при скупке. Ниже числа диагностики ноутбука и цена по формуле. Верни ТОЛЬКО JSON вида {"extra_discount_pct": число от 0 до 15, "note": "одно короткое предложение по-русски"}. extra_discount_pct это дополнительная уценка поверх формулы, только если износ батареи или состояние SSD явно хуже типичного для такой цены; иначе 0. Не придумывай факты.

Износ батареи, %: ' + d.device.battery_wear_pct + '
Циклов батареи: ' + (d.device.battery_cycles === null ? 'нет данных' : d.device.battery_cycles) + '
Здоровье SSD, %: ' + d.device.ssd_health_pct + '
Базовая цена, руб.: ' + d.base_price + '
Цена по формуле, руб.: ' + d.price_formula;
return { json: { ...d, prompt } };

// Итог с расчётом Ollama: дополнительная уценка модели ограничена диапазоном 0-15%, битый ответ даёт 0%. Решение о цене остаётся за человеком.
const d = $('Подготовить запрос к Ollama').item.json;
let extra = 0, note = '';
try {
  const j = JSON.parse(String($json.response || '{}'));
  const n = Number(j.extra_discount_pct);
  extra = Number.isFinite(n) ? Math.min(15, Math.max(0, n)) : 0;
  note = String(j.note || '').replace(/[\r\n]+/g, ' ').slice(0, 240);
} catch (e) { extra = 0; note = ''; }
const limit = Math.round(d.price_formula * (1 - extra / 100) / 100) * 100;
const lines = [
  'Ноутбук ' + (d.device.model || 'без модели') + ' · ' + d.device.board_serial,
  'АКБ износ ' + d.device.battery_wear_pct + '% · SSD ' + d.device.ssd_health_pct + '% · флагов MDM и Autopilot не найдено',
  'Лимит цены: до ' + String(limit).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽ (формула ' + d.price_formula + ' ₽, уценка Ollama ' + extra + '%)',
];
if (note) lines.push('Заметка модели: ' + note);
lines.push('Пример расчёта: решение о цене за человеком.');
return { json: { device: d.device, verdict: 'allow', reasons: d.reasons, base_price: d.base_price, price_limit: limit, extra_discount_pct: extra, ollama_note: note, text: lines.join('\n') } };

// Итог без расчёта Ollama: запрет или ручная проверка. Блокировки не снимаются и не обходятся, система только сообщает о найденных следах.
const d = $json;
const head = d.verdict === 'forbidden' ? 'СДЕЛКА ЗАПРЕЩЕНА' : 'Нужна ручная проверка';
const text = head + ': ' + (d.device.model || 'без модели') + ' · ' + d.device.board_serial + '\n' + d.reasons.map((r) => '- ' + r).join('\n') + (d.verdict === 'forbidden' ? '\nЦену не называть. Передать решение руководителю приёмки.' : '\nДо проверки цену не называть.');
return { json: { device: d.device, verdict: d.verdict, reasons: d.reasons, base_price: d.base_price, price_limit: null, extra_discount_pct: 0, ollama_note: '', text } };

// Итог берётся из той ветки, которая выполнялась (с Ollama или без).
let f;
try { f = $('Итог с Ollama').item.json; } catch (e) { f = $('Итог без Ollama').item.json; }
return { json: { ...f, id: $json.id || null } };
